#!/usr/bin/env bash
# One-time: teach k3s containerd that the in-cluster registry serves HTTPS and
# requires a client certificate.
#
#   sudo ./k8s/ci/setup-registry.sh
#
# kubelet/containerd run on the host, outside the pod network, so they cannot
# resolve registry.pfa.svc. The NodePort on loopback is stable regardless of
# the node's LAN IP, and the registry certificate carries a 127.0.0.1 SAN for
# exactly this dial.
#
# The certificate material comes from .certs/, generated by
# ./k8s/ci/gen-tls-certs.sh. It is copied to /etc/rancher/k3s/registry-certs/
# because k3s reads registries.yaml at startup and both the config and the
# files it names must survive reboots.
#
# Idempotent: safe to rerun. Restarts k3s (~30 s, pods keep their state).
#
# Ordering: run this in the same window as the registry Deployment roll-out.
# If registries.yaml says HTTPS while the registry still serves HTTP (or the
# reverse), image *pulls* fail until both sides agree. Running pods are
# unaffected; already-cached images stay usable.
set -euo pipefail

if [[ "${EUID}" -ne 0 ]]; then
  echo "Run with sudo: sudo $0" >&2
  exit 1
fi

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
CERT_SRC="${CERT_DIR:-${ROOT_DIR}/.certs}"
REGISTRY_ADDR="${REGISTRY_ADDR:-127.0.0.1:30500}"
CERT_DEST=/etc/rancher/k3s/registry-certs
TARGET=/etc/rancher/k3s/registries.yaml

for f in ca.crt registry-client.crt registry-client.key; do
  [[ -f "${CERT_SRC}/${f}" ]] || {
    echo "Missing ${CERT_SRC}/${f}" >&2
    echo "Generate it first: ./k8s/ci/gen-tls-certs.sh" >&2
    echo "(or point CERT_DIR at a copy of .certs/)" >&2
    exit 1
  }
done

echo "==> Installing certificates in ${CERT_DEST}"
mkdir -p "${CERT_DEST}"
install -m 0644 -o root -g root "${CERT_SRC}/ca.crt"     "${CERT_DEST}/ca.crt"
# skopeo/containers-image naming: the client cert is *.cert, the key *.key.
# This is the registry-client identity; the runner's buildkit client cert is
# signed by a CA the registry no longer trusts.
install -m 0600 -o root -g root "${CERT_SRC}/registry-client.crt" "${CERT_DEST}/client.cert"
install -m 0600 -o root -g root "${CERT_SRC}/registry-client.key" "${CERT_DEST}/client.key"

echo "==> Writing ${TARGET} (mTLS endpoint https://${REGISTRY_ADDR})"
mkdir -p /etc/rancher/k3s
cat > "${TARGET}" <<YAML
mirrors:
  "${REGISTRY_ADDR}":
    endpoint:
      - "https://${REGISTRY_ADDR}"
configs:
  "${REGISTRY_ADDR}":
    tls:
      ca_file: ${CERT_DEST}/ca.crt
      cert_file: ${CERT_DEST}/client.cert
      key_file: ${CERT_DEST}/client.key
YAML
chmod 0644 "${TARGET}"

echo "==> Restarting k3s"
systemctl restart k3s

echo
echo "Done. Give k3s ~30 s, then verify from the host:"
echo "  kubectl --kubeconfig ~/.kube/k3s.yaml get nodes"
echo "  curl --cacert ${CERT_SRC}/ca.crt --cert ${CERT_SRC}/registry-client.crt \\"
echo "       --key ${CERT_SRC}/registry-client.key https://${REGISTRY_ADDR}/v2/"
